    list_cards: {
        parameters: {
            query?: {
                /**
                 * @description The account filter, `ACCTSIDI X(11)`: 11 digits, or blank or all zeros
                 *     for no filter (`2210-EDIT-ACCOUNT`).
                 */
                account_id?: string;
                /**
                 * @description The card filter, `CARDSIDI X(16)`: 16 digits, or blank or all zeros
                 *     for no filter (`2220-EDIT-CARD`).
                 */
                card_number?: string;
                /**
                 * @description The card number the page starts from, `CARD-NUM` `X(16)` in ASCII
                 *     without NUL characters: a previous page's `next_key` or `prev_key`.
                 *     Forward (ENTER, PF8), the page starts at that card, inclusive;
                 *     backward (PF7), it holds the cards before it. Absent, both directions
                 *     read the first page.
                 */
                start_key?: string;
                /** @description `forward` (ENTER and PF8, the default) or `backward` (PF7). */
                direction?: "forward" | "backward";
                /**
                 * @description Rows on the page, from 1 to 100. Defaults to 7, the rows of the
                 *     `COCRDLI` screen.
                 */
                page_size?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description One page of cards in card-number order, with the keys of its neighbours and the COBOL page text */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Page_CardSummary"];
                };
            };
            /** @description A filter or page parameter the COBOL edits reject, or a start key longer than 16 characters, not ASCII or holding a NUL character */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorBody"];
                };
            };
            /** @description No valid bearer token */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorBody"];
                };
            };
            /** @description The card file could not be read */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorBody"];
                };
            };
        };
    };
